/** Text split into plain parts and {references}, for display in bold. */
export function textParts(text: string): { text: string; ref: boolean }[] {
  return text
    .split(/(\{[^}]+\})/)
    .filter(Boolean)
    .map((p) =>
      p.startsWith("{") ? { text: p.slice(1, -1), ref: true } : { text: p, ref: false },
    );
}

/** Every {reference} in the text. */
export function textRefs(text: string): string[] {
  return textParts(text)
    .filter((p) => p.ref)
    .map((p) => p.text);
}
